/**
 * The Tourney Marshal — structural test generated by compile:encounter (THR-1246).
 * Expected values are baked from the content package, so this file asserts the
 * encounter's actual shape rather than any template's.
 */

import { describe, expect, it } from 'vitest';
import { TOURNEY_MARSHAL_TEMPLATE } from '../tourney-marshal';
import { expandSettings } from '../../settingClasses';
import { drawConsequenceHand, handAfterSwap } from '../../content-eval/consequenceDraw';

describe("The Tourney Marshal — template structure", () => {
  it('carries its identity', () => {
    expect(TOURNEY_MARSHAL_TEMPLATE.id).toBe('encounter.town.tourney_marshal');
    expect(TOURNEY_MARSHAL_TEMPLATE.reach).toBe('iron');
    expect(TOURNEY_MARSHAL_TEMPLATE.rarityTier).toBe(2);
    expect(TOURNEY_MARSHAL_TEMPLATE.steps).toHaveLength(2);
  });

  it('step 0 deals the authored hand', () => {
    const step = TOURNEY_MARSHAL_TEMPLATE.steps[0];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['tourney.stiffen_the_barrier', 'tourney.halt_the_blade']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['force', 'time']);
  });

  it('step 1 deals the authored hand', () => {
    const step = TOURNEY_MARSHAL_TEMPLATE.steps[1];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['tourney.give_the_word_weight', 'tourney.dull_the_sword_arm']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['entropy', 'order']);
  });
  it('derives its location subtypes from the declared envelope', () => {
    expect(TOURNEY_MARSHAL_TEMPLATE.settings).toEqual(['urban']);
    expect(TOURNEY_MARSHAL_TEMPLATE.locationSubtypes).toEqual(expandSettings(['urban']));
  });

  it('records exactly the hand its id draws (binding, THR-1145)', () => {
    expect(TOURNEY_MARSHAL_TEMPLATE.consequenceDraw).toEqual(['condition', 'secret']);
    expect(TOURNEY_MARSHAL_TEMPLATE.consequenceDraw).toEqual(
      handAfterSwap(
        drawConsequenceHand({
          templateId: 'encounter.town.tourney_marshal',
          reach: 'iron',
          rarityTier: 2,
        }),
        TOURNEY_MARSHAL_TEMPLATE.consequenceSwap,
      ),
    );
  });
});
